CREATE TABLE ecommerce_sales (Sale_ID INT PRIMARY KEY,Order_Date DATETIME,Delivery_Date DATETIME,Customer_ID VARCHAR(10),Customer_Name VARCHAR(50),Age INT,Gender VARCHAR(10),City VARCHAR(40),State VARCHAR(40),Region VARCHAR(20),Product_ID VARCHAR(10),Product_Name VARCHAR(80),Category VARCHAR(40),Sub_Category VARCHAR(40),Quantity INT,Unit_Price DECIMAL(10,2),Discount DECIMAL(5,2),Sales DECIMAL(10,2),Payment_Mode VARCHAR(20),Salesperson VARCHAR(40),Delivery_Status VARCHAR(20));

